  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── 1. PROFESSOR ───────────────────────────────────────────────\nmodel Professor {\n  id                  String   @id @default(uuid())\n  nome                String\n  email               String   @unique\n  senha               String\n  telefone            String?\n  codigoConvite       String?\n  cursos              String[]\n  expoPushToken       String?\n  chavePix            String?\n  linkPagamentoCartao String?\n\n  alunos       Aluno[]\n  aulas        Aula[]\n  pagamentos   Pagamento[]\n  materiais    Material[]\n  reposicoes   Reposicao[]\n  notificacoes Notificacao[]\n  mensagens    Mensagem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── 2. ALUNO ────────────────────────────────────────────────────\nmodel Aluno {\n  id            String  @id @default(uuid())\n  nome          String\n  email         String  @unique\n  senha         String\n  telefone      String?\n  curso         String?\n  expoPushToken String? // Token para push notifications\n\n  status             String    @default(\"PENDENTE\") // PENDENTE, ATIVO, INATIVO\n  valorMensalidade   Float?\n  diaVencimento      Int?\n  recorrenciaAula    String? // SEMANAL, QUINZENAL, MENSAL\n  diaSemanaAula      String? // Ex: \"Segunda-feira\"\n  diaSemanaNumero    Int? // 0=Dom … 6=Sáb (para geração de aulas)\n  horarioAula        String? // Ex: \"14:30\"\n  tempoContrato      Int? // Em meses\n  dataInicioContrato DateTime? // Data de ativação do contrato\n\n  createdAt DateTime @default(now())\n\n  professorId String\n  professor   Professor @relation(fields: [professorId], references: [id])\n\n  aulas      Aula[]\n  pagamentos Pagamento[]\n  reposicoes Reposicao[]\n  mensagens  Mensagem[]\n}\n\n// ─── 3. AULAS & AGENDA ───────────────────────────────────────────\nmodel Aula {\n  id       String   @id @default(uuid())\n  tema     String?\n  dataHora DateTime\n  status   String   @default(\"AGENDADA\") // AGENDADA, CONCLUIDA, CANCELADA\n  tipo     String   @default(\"REGULAR\") // REGULAR, REPOSICAO\n  presenca String? // PRESENTE, AUSENCIA_PROFESSOR, AUSENCIA_ALUNO, PENDENTE_REPOSICAO\n\n  professorId String\n  professor   Professor  @relation(fields: [professorId], references: [id])\n  alunoId     String\n  aluno       Aluno      @relation(fields: [alunoId], references: [id])\n  materiais   Material[]\n\n  createdAt DateTime @default(now())\n}\n\n// ─── 4. FINANCEIRO & PAGAMENTOS ──────────────────────────────────\nmodel Pagamento {\n  id             String    @id @default(uuid())\n  valor          Float\n  vencimento     DateTime\n  dataPagamento  DateTime?\n  status         String    @default(\"PENDENTE\") // PENDENTE, PAGO, ATRASADO, EM_ANALISE\n  comprovanteUrl String?\n  metodo         String? // PIX, CARTAO, BOLETO\n\n  professorId String\n  professor   Professor @relation(fields: [professorId], references: [id])\n  alunoId     String\n  aluno       Aluno     @relation(fields: [alunoId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── 5. MATERIAIS DIDÁTICOS ──────────────────────────────────────\nmodel Material {\n  id       String  @id @default(uuid())\n  titulo   String\n  tipo     String // PDF, VIDEO, AUDIO, TEXTO\n  url      String?\n  conteudo String?\n\n  professorId String\n  professor   Professor @relation(fields: [professorId], references: [id])\n  alunoId     String?\n  aulaId      String?\n  aula        Aula?     @relation(fields: [aulaId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\n// ─── 6. MENSAGENS DO CHAT ────────────────────────────────────────\nmodel Mensagem {\n  id          String     @id @default(uuid())\n  texto       String\n  remetente   String // alunoId (UUID) | \"professor\"\n  alunoId     String?\n  aluno       Aluno?     @relation(fields: [alunoId], references: [id])\n  professorId String?\n  professor   Professor? @relation(fields: [professorId], references: [id])\n  createdAt   DateTime   @default(now())\n}\n\n// ─── 7. NOTIFICAÇÕES ─────────────────────────────────────────────\nmodel Notificacao {\n  id         String  @id @default(uuid())\n  tipo       String // CONTRATO_EXPIRADO, CONTRATO_EXPIRANDO, NOVO_ALUNO, etc.\n  titulo     String\n  mensagem   String\n  lida       Boolean @default(false)\n  dadosExtra String? // JSON serializado com dados adicionais (alunoId, etc.)\n\n  professorId String\n  professor   Professor @relation(fields: [professorId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\n// ─── 8. TOKEN DE REDEFINIÇÃO DE SENHA ───────────────────────────\nmodel TokenRedefinicaoSenha {\n  id        String   @id @default(uuid())\n  email     String\n  token     String   @unique\n  expiresAt DateTime\n  usado     Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\n// ─── 9. REPOSIÇÕES ───────────────────────────────────────────────\nmodel Reposicao {\n  id           String   @id @default(uuid())\n  professorId  String\n  alunoId      String\n  dataOriginal String?\n  dataProposta String\n  motivo       String\n  status       String   @default(\"AGUARDANDO\")\n  createdAt    DateTime @default(now())\n\n  professor Professor @relation(fields: [professorId], references: [id])\n  aluno     Aluno     @relation(fields: [alunoId], references: [id])\n}\n",
